import pandas as pd
import numpy as np

DATASET_PATH = "chunks_csv/cyclehire_w003.csv"
ADJACENCY_PATH = "chunks_csv/borough_adjacency.csv"

# Step 1: Compute Self-Containment Index (SCI)
df = pd.read_csv(DATASET_PATH)
departures = df['StartBorough'].value_counts()
self_contained = df[df['StartBorough'] == df['EndBorough']]['StartBorough'].value_counts()
arrivals = df['EndBorough'].value_counts()
total_trips = arrivals.sum()

arrival_share = arrivals / total_trips
expected_self_contained = departures * arrival_share
sci = self_contained / expected_self_contained
sci_df = pd.DataFrame({
    'SCI': sci
}).fillna(0)  # Handle boroughs with zero departures

# Step 2: Build adjacency list
adj_df = pd.read_csv(ADJACENCY_PATH)
adjacency = {}
for _, row in adj_df.iterrows():
    borough = row['borough']
    neighbor = row['neighbor']
    if borough not in adjacency:
        adjacency[borough] = []
    adjacency[borough].append(neighbor)

# Step 3: Compute average neighbor SCI for each borough
borough_list = sci_df.index.tolist()
sci_values = sci_df['SCI'].values
neighbor_avg_sci = {}
for borough in borough_list:
    neighbors = adjacency.get(borough, [])
    neighbor_scis = [sci_df.loc[n, 'SCI'] for n in neighbors if n in sci_df.index]
    if neighbor_scis:
        neighbor_avg_sci[borough] = np.mean(neighbor_scis)
    else:
        neighbor_avg_sci[borough] = np.nan  # No neighbors

# Step 4: Permutation test for spatial clustering
num_permutations = 500
observed_neighbor_avg = {b: neighbor_avg_sci[b] for b in borough_list}
p_values = {b: 0 for b in borough_list}

for _ in range(num_permutations):
    # Shuffle SCI values
    shuffled_scis = sci_values.copy()
    np.random.shuffle(shuffled_scis)
    shuffled_sci_dict = dict(zip(borough_list, shuffled_scis))

    # Compute neighbor averages under shuffled assignment
    shuffled_neighbor_avg = {}
    for borough in borough_list:
        neighbors = adjacency.get(borough, [])
        neighbor_scis = [shuffled_sci_dict[n] for n in neighbors if n in shuffled_sci_dict]
        if neighbor_scis:
            shuffled_neighbor_avg[borough] = np.mean(neighbor_scis)
        else:
            shuffled_neighbor_avg[borough] = np.nan

    # Compare to observed
    for borough in borough_list:
        if np.isnan(observed_neighbor_avg[borough]):
            continue
        if np.isnan(shuffled_neighbor_avg[borough]):
            continue
        if observed_neighbor_avg[borough] >= shuffled_neighbor_avg[borough]:
            p_values[borough] += 1

# Normalize p-values
for b in p_values:
    p_values[b] /= num_permutations

# Step 5: Identify hot/cold spots
hot_spots = []
cold_spots = []
median_sci = np.nanmedian(sci_df['SCI'])

for borough in borough_list:
    sci_val = sci_df.loc[borough, 'SCI']
    avg_neighbor_sci = neighbor_avg_sci[borough]
    p = p_values[borough]

    if np.isnan(avg_neighbor_sci) or np.isnan(sci_val):
        continue

    # Hot spot: high SCI and high neighbor SCI, p < 0.05
    if sci_val > median_sci and avg_neighbor_sci > median_sci and p < 0.05:
        hot_spots.append((borough, sci_val, p))
    # Cold spot: low SCI and low neighbor SCI, p < 0.05
    elif sci_val < median_sci and avg_neighbor_sci < median_sci and p < 0.05:
        cold_spots.append((borough, sci_val, p))

# Format final answer
final_answer = []
for b, sci_val, p in hot_spots:
    final_answer.append(f"{b} (HH, statistical method={p:.3f})")
for b, sci_val, p in cold_spots:
    final_answer.append(f"{b} (LL, statistical method={p:.3f})")

print("FINAL ANSWER: " + ", ".join(final_answer) if final_answer else "FINAL ANSWER: none")
